/* Editorial study routes shared by Radar, Hub and the standalone offline app. */
import {topics as radarTopics} from './radar-data';
export type ArgumentIdea = { claim:string; reason:string; example:string; question:string };
export type InterventionIdea = { agente:string; acao:string; meio:string; finalidade:string };
export type EssayRoute = { id:string; label:string; thesis:string; arguments:[ArgumentIdea,ArgumentIdea]; intervention:InterventionIdea; care:string };
export type EssayIdeaTopic = { id:string; title:string; axis:string; proposals:[string,string,string]; keywords:string[]; routes:[EssayRoute,EssayRoute]; concepts:[{title:string;text:string},{title:string;text:string}]; questions:[string,string,string]; sources:[{title:string;url:string}] };
const arg=(claim:string,reason:string,example:string,question:string):ArgumentIdea=>({claim,reason,example,question});
const fix=(agente:string,acao:string,meio:string,finalidade:string):InterventionIdea=>({agente,acao,meio,finalidade});
const route=(id:string,label:string,thesis:string,a:ArgumentIdea,b:ArgumentIdea,intervention:InterventionIdea,care:string):EssayRoute=>({id,label,thesis,arguments:[a,b],intervention,care});
const officialINEP="https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel";
export const essayIdeas:EssayIdeaTopic[]=[
 {id:'leitura',title:'Leitura, livros e formação de leitores',axis:'Educação e cultura',proposals:['Desafios para democratizar o acesso à leitura e formar leitores no Brasil','Caminhos para ampliar o acesso à leitura no Brasil','Como aproximar jovens brasileiros dos livros e das bibliotecas'],keywords:['biblioteca','livro','letramento','leitor','leitura escolar','mediação cultural','livraria'],routes:[
  route('territorio','Território e mediação','O acesso desigual a espaços de leitura e a pouca mediação no cotidiano escolar limitam a formação de leitores, sobretudo onde bibliotecas e atividades culturais são escassas.',arg('A distribuição desigual de bibliotecas e acervos restringe as oportunidades de leitura.','Quando o contato com livros depende da renda familiar ou do endereço, a leitura deixa de ser uma experiência acessível e vira vantagem acumulada.','Uma turma pode comparar, em um mapa do município, a distância entre bairros e bibliotecas públicas; trate isso como exemplo hipotético, salvo pesquisa local.','Que barreira concreta impede esse leitor de chegar a um livro?'),arg('A leitura perde continuidade quando a escola a apresenta apenas como obrigação avaliativa.','Sem escolha, conversa e acompanhamento, muitos estudantes não encontram motivos para relacionar a leitura à própria vida.','Um clube de leitura que permita escolher entre conto, quadrinho e crônica pode favorecer participação; avalie a experiência antes de afirmar resultado.','Como a escola transforma o primeiro contato em hábito, sem impor um único gosto?'),fix('Secretarias municipais e estaduais de Educação e Cultura','Criar circuitos permanentes de leitura em bairros com menor oferta cultural.','Integrar bibliotecas itinerantes, acervos acessíveis e rodas de leitura mediadas por profissionais em escolas e equipamentos comunitários.','Ampliar o acesso e fortalecer a formação de leitores em diferentes territórios.'),'Não reduza o problema a “falta de interesse”: investigue oferta, acessibilidade e experiências anteriores.'),
  route('pertencimento','Pertencimento e diversidade','Formar leitores exige reconhecer repertórios culturais plurais e oferecer materiais acessíveis; a ausência de representatividade pode afastar estudantes dos espaços de leitura.',arg('Acervos homogêneos silenciam experiências de parte dos leitores.','Quando livros não dialogam com diferentes origens, territórios, deficiências e modos de vida, a escola perde oportunidades de identificação e descoberta.','Uma biblioteca escolar pode revisar, com os alunos, a variedade de autores, formatos e personagens do acervo — ação que precisa ser verificada na prática.','Quem encontra sua experiência nos materiais oferecidos? Quem ainda fica de fora?'),arg('Barreiras físicas e comunicacionais tornam uma biblioteca formalmente aberta, mas difícil de usar.','Pessoas com deficiência, leitores iniciantes e quem dispõe de pouco tempo precisam de condições concretas para participar.','Audiolivros, texto acessível e horário ampliado são possibilidades; a escolha depende do público e da estrutura local.','Que ajuste removeria a barreira identificada sem presumir as necessidades do público?'),fix('Equipes das redes de ensino e bibliotecas públicas','Implantar curadoria participativa de acervos e planos de acessibilidade.','Ouvir estudantes e comunidades, diversificar formatos e acompanhar empréstimos e pedidos não atendidos para revisar a oferta.','Construir espaços de leitura representativos, acessíveis e acolhedores.'),'Evite usar representatividade como palavra decorativa; mostre qual barreira ela ajuda a enfrentar.')],concepts:[{title:'Letramento como prática social',text:'Observe os usos da leitura em situações reais, não apenas a decodificação de palavras.'},{title:'Mediação cultural',text:'Pense em quem aproxima o acervo do leitor, que escolhas oferece e como escuta sua resposta.'}],questions:['O argumento explica uma causa ou só repete que “ler é importante”?','A proposta chega aos leitores afetados e considera barreiras de acesso?','O exemplo é verificável ou está identificado como hipotético?'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'digital',title:'Proteção de crianças no ambiente digital',axis:'Infância e juventude',proposals:['Caminhos para proteger crianças e adolescentes nos ambientes digitais brasileiros','Desafios para conciliar participação online e proteção da infância','Responsabilidade coletiva no ambiente digital vivido por crianças'],keywords:['infância','criança','adolescente','eca digital','publicidade infantil','redes sociais','plataformas','tela'],routes:[
  route('responsabilidade','Responsabilidade e desenho das plataformas','A exposição de crianças a riscos digitais é ampliada por serviços projetados para prolongar engajamento e por respostas de proteção pouco claras para famílias e usuários.',arg('Mecanismos de recomendação e interação podem manter o público jovem exposto a conteúdo inadequado.','Recursos persuasivos, publicidade e coleta de dados tornam difícil para uma criança reconhecer riscos ou interromper o uso por conta própria.','Uma análise de interface pode observar como recomendações e avisos aparecem em um perfil de teste; não atribua a uma empresa um efeito sem fonte.','Que parte do funcionamento do serviço está fora do controle de uma criança?'),arg('A responsabilidade é distribuída de forma desigual entre plataformas, responsáveis e escola.','Orientar famílias sem exigir transparência e proteção técnica transfere o peso para quem menos conhece o funcionamento dos sistemas.','Uma oficina pode comparar configurações de privacidade e canais de denúncia de serviços usados pela comunidade, registrando limites encontrados.','Qual ator tem poder real para reduzir a exposição e qual atribuição lhe cabe?'),fix('Poder Público e empresas de tecnologia, com participação de famílias e especialistas','Fortalecer padrões de proteção por idade e canais de denúncia compreensíveis.','Publicar orientações em linguagem simples, revisar mecanismos de recomendação e encaminhar relatos a equipes treinadas, com transparência e respeito à privacidade.','Reduzir riscos digitais sem expulsar crianças dos espaços de aprendizagem e participação.'),'Não trate vigilância total nem proibição de internet como solução suficiente; considere privacidade e autonomia progressiva.'),
  route('alfabetizacao','Educação digital e rede de cuidado','A proteção online depende tanto de ferramentas preventivas quanto da capacidade de crianças e adultos reconhecerem riscos, conversar sobre eles e buscar ajuda.',arg('O letramento digital insuficiente dificulta identificar publicidade, manipulação e pedidos de dados.','Saber acessar um aplicativo não significa compreender seus incentivos ou avaliar a origem de uma mensagem.','Uma turma pode classificar exemplos fictícios de anúncio, opinião e notícia antes de discutir como verificá-los.','Que habilidade prática ajuda a criança a tomar uma decisão mais informada?'),arg('O silêncio e o medo de punição podem atrasar a procura de apoio.','Quando adultos respondem com culpa ou confisco automático, jovens podem esconder situações de assédio ou exposição.','Uma escola pode criar um protocolo de acolhimento com escuta reservada e contatos de proteção, validado com a comunidade escolar.','Como acolher a revelação de um risco preservando a dignidade da criança?'),fix('Escolas e redes de proteção da infância','Oferecer educação digital acompanhada de um fluxo seguro de acolhimento.','Realizar atividades com cenários fictícios, informar canais locais de ajuda e orientar profissionais sobre encaminhamento responsável.','Aumentar a autonomia para reconhecer riscos e facilitar a busca de apoio.'),'Evite culpabilizar crianças, famílias ou vítimas por falhas de desenho e moderação de serviços.')],concepts:[{title:'Proteção integral',text:'Analise deveres de cuidado de acordo com a idade e os direitos envolvidos.'},{title:'Letramento midiático',text:'Ensinar a perguntar quem publicou, com qual interesse e como conferir uma informação.'}],questions:['O texto distingue risco, responsabilidade e evidência?','A proteção preserva privacidade, participação e autonomia progressiva?','A intervenção inclui um canal claro para buscar ajuda?'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'clima',title:'Crise climática e cidades vulneráveis',axis:'Meio ambiente',proposals:['Desafios para proteger populações vulneráveis dos desastres climáticos no Brasil','Caminhos para adaptar cidades brasileiras a eventos climáticos extremos','Desigualdade territorial e prevenção de desastres no Brasil'],keywords:['enchente','chuva','seca','desastre','clima','aquecimento','adaptação urbana','defesa civil','risco ambiental'],routes:[
  route('prevencao','Prevenção e desigualdade territorial','Impactos climáticos tornam-se mais graves quando o planejamento urbano não reduz a exposição de moradias vulneráveis nem oferece alertas e rotas de evacuação acessíveis.',arg('Ocupação precária em áreas de risco expõe moradores a desastres previsíveis.','A desigualdade no acesso à moradia segura limita escolhas; responsabilizar quem vive nessas áreas esconde a falta de alternativas.','Um estudo de caso municipal pode mapear moradias próximas a encostas ou cursos d’água, com dados e metodologia citados.','Que decisão de planejamento aumentou a exposição, e que evidência local permite demonstrá-lo?'),arg('Alertas e planos que não chegam a todos reduzem o tempo de resposta.','Avisos técnicos sem linguagem clara, redundância ou rota acessível podem deixar de orientar pessoas com necessidades diversas.','Uma simulação escolar pode testar se uma família receberia um alerta em áreas com sinal instável; identifique-a como exercício.','Quem pode não receber o aviso e qual alternativa de comunicação alcança essa pessoa?'),fix('Prefeituras e órgãos de Defesa Civil','Mapear riscos e adotar planos locais de prevenção e resposta.','Combinar vistorias técnicas, alertas em múltiplos canais, rotas acessíveis e participação comunitária nos exercícios.','Reduzir a exposição ao risco e proteger a população antes e durante eventos extremos.'),'Não apresente um evento climático isolado como prova de uma tendência; use séries e fontes verificáveis.'),
  route('adaptacao','Adaptação urbana e recuperação','A vulnerabilidade climática persiste quando infraestrutura e políticas de recuperação ignoram diferenças de renda, mobilidade e acesso a serviços.',arg('Infraestrutura urbana impermeável e drenagem insuficiente podem agravar alagamentos.','A forma de ocupar o solo interfere no escoamento; obras precisam considerar bacia, manutenção e mudanças no uso do território.','Compare projetos locais de drenagem e áreas verdes com mapas públicos, sem afirmar a eficácia antes de avaliar resultados.','Qual mecanismo urbano conecta a intervenção proposta ao risco?'),arg('A reconstrução após um desastre pode reproduzir a vulnerabilidade.','Se a recuperação não oferecer moradia segura, renda e participação, famílias podem retornar a áreas de risco por falta de alternativa.','Uma audiência comunitária hipotética pode levantar necessidades de abrigo, transporte e documentação antes de planejar a resposta.','O que a recuperação precisa garantir além de reparar prédios?'),fix('Prefeituras e Defesa Civil, com apoio das áreas de habitação e assistência social','Integrar adaptação climática a obras urbanas e aos planos de reconstrução.','Priorizar áreas mapeadas, publicar critérios, ouvir moradores e monitorar manutenção das estruturas implementadas.','Diminuir danos e evitar que a recuperação reforce desigualdades existentes.'),'Diferencie mitigação das emissões, adaptação a impactos e resposta emergencial.')],concepts:[{title:'Vulnerabilidade socioambiental',text:'Cruza exposição a perigos com renda, moradia, infraestrutura e capacidade de resposta.'},{title:'Adaptação climática',text:'Preparar sistemas e territórios para impactos observados e projetados com base em avaliações.'}],questions:['O texto identificou a população e o risco concretos?','A solução também previne, em vez de só socorrer?','Cite dados climáticos apenas com fonte, período e recorte territorial.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'mental',title:'Saúde mental e hiperconexão',axis:'Saúde',proposals:['Desafios para o cuidado com a saúde mental de jovens em uma sociedade hiperconectada','Como promover bem-estar digital entre jovens no Brasil','Acolhimento e saúde mental de estudantes brasileiros'],keywords:['ansiedade','saúde mental','jovem','hiperconexão','sono','bem-estar','rede social','atenção psicossocial'],routes:[
  route('acolhimento','Acolhimento e acesso ao cuidado','O sofrimento psíquico entre jovens pode ser agravado por pressões digitais e pela dificuldade de acessar escuta e atendimento contínuos.',arg('Comparação social e pressão por disponibilidade podem afetar o bem-estar.','Exposição repetida a conteúdos e expectativas pode influenciar hábitos e autoimagem, mas efeitos variam entre pessoas.','Uma pesquisa escolar anônima e voluntária pode perguntar sobre hábitos sem coletar nomes ou diagnosticar estudantes.','Que mecanismo foi observado e quais limites impedem generalizá-lo?'),arg('Acolhimento tardio deixa estudantes sem apoio quando percebem sinais de sofrimento.','Estigma, filas e falta de articulação entre escola, família e rede de saúde dificultam a busca por ajuda qualificada.','Um fluxo de encaminhamento escolar pode informar a quem recorrer sem transformar professor em terapeuta.','Quem deve ouvir e encaminhar sem assumir uma função clínica que não lhe cabe?'),fix('Secretarias de Saúde e Educação','Ampliar ações de promoção de bem-estar e acesso a atendimento psicossocial.','Capacitar equipes para acolhimento inicial, informar a rede disponível e articular encaminhamentos com profissionais habilitados.','Facilitar a busca precoce por cuidado apropriado e respeitar a singularidade dos jovens.'),'Não diagnostique leitor ou grupo, nem atribua todo sofrimento ao uso de telas.'),
  route('bem-estar','Hábitos digitais e ambientes de estudo','Promover bem-estar exige combinar autonomia para organizar hábitos de conexão com ambientes educacionais que não naturalizem exaustão ou isolamento.',arg('A disponibilidade permanente pode comprometer descanso e concentração.','Notificações e cobrança por resposta imediata fragmentam períodos de estudo e descanso, sobretudo quando não há regras coletivas.','Uma turma pode pactuar horários sem notificações durante atividades e avaliar se a medida ajuda diferentes estudantes.','A mudança depende apenas do indivíduo ou também das regras do ambiente?'),arg('A escola pode abrir espaço para conversar sobre emoções sem estigmatizar.','Atividades de escuta e convivência ajudam a sinalizar caminhos de apoio, mas não substituem cuidado profissional.','Uma roda com participação voluntária pode mapear fontes de estresse e encaminhar demandas sem expor relatos individuais.','Como criar participação sem exigir que alguém revele informações privadas?'),fix('Escolas, famílias e equipes de saúde locais','Adotar iniciativas de bem-estar digital e orientação de saúde mental.','Criar acordos de convivência, oficinas de uso consciente e materiais claros sobre serviços de atendimento da rede.','Reduzir barreiras à organização de hábitos e à procura de apoio qualificado.'),'Não recomende interromper tratamento nem troque informação clínica por opinião de internet.')],concepts:[{title:'Promoção da saúde',text:'Tratar bem-estar como resultado de condições, vínculos e acesso a serviços, não só vontade individual.'},{title:'Determinantes sociais',text:'Observar como renda, escola, território e relações alteram a possibilidade de cuidar da saúde.'}],questions:['A proposta respeita sigilo, voluntariedade e limite entre escola e serviço clínico?','Você evitou atribuir causalidade clínica sem pesquisa apropriada?','Que ambiente ou prática coletiva também precisa mudar?'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'ia',title:'Inteligência artificial e desinformação',axis:'Tecnologia e informação',proposals:['Caminhos para enfrentar a desinformação amplificada pela inteligência artificial no Brasil','Desafios para identificar conteúdos sintéticos enganosos','Educação midiática e confiança em informação digital'],keywords:['desinformação','inteligência artificial','deepfake','notícia falsa','conteúdo sintético','educação midiática','verificação digital'],routes:[
  route('verificacao','Verificação e letramento midiático','Conteúdos fabricados ou alterados por IA podem circular com rapidez, enquanto a baixa educação midiática dificulta verificar autoria, contexto e evidências.',arg('Imagens e áudios convincentes reduzem a confiança em sinais visuais familiares.','Ferramentas que geram conteúdo elevam a escala da produção; por isso, aparência não substitui confirmação por fonte independente.','Uma atividade pode comparar uma mensagem inventada com um comunicado autêntico disponível em canal oficial.','Que elemento foi checado além da aparência do conteúdo?'),arg('A circulação repetida leva a pessoa a encontrar informação antes de saber avaliá-la.','Recomendações e compartilhamentos podem acelerar conteúdos emocionais; as condições variam por plataforma e contexto.','Uma turma pode rastrear, em exemplos simulados, quem publicou primeiro e quais fontes documentam a alegação.','Que evidência independente sustenta ou contradiz essa alegação?'),fix('Redes de ensino e instituições de comunicação pública','Ensinar verificação de fontes, contexto e autoria em atividades permanentes.','Usar exemplos simulados, roteiros de checagem e acesso direto a canais oficiais, com revisão periódica do material.','Aumentar a capacidade de avaliar conteúdos antes de compartilhá-los.'),'Não declare que um detector de IA prova autoria ou falsidade: essas ferramentas podem errar.'),
  route('transparencia','Transparência e circulação responsável','Enfrentar desinformação exige mecanismos que informem como conteúdos sintéticos são apresentados e ofereçam respostas rastreáveis a relatos dos usuários.',arg('A ausência de contexto sobre conteúdo gerado ou editado dificulta a avaliação do público.','Sinais claros de origem podem apoiar a análise, embora não comprovem por si sós a verdade do conteúdo.','Uma plataforma poderia testar avisos visíveis e um histórico de edição, medindo se usuários os percebem.','O aviso identifica origem sem alegar certeza sobre a veracidade?'),arg('A moderação sem explicação pode remover conteúdo legítimo ou falhar diante de manipulação.','Regras pouco claras impedem contestação e correção, enquanto decisões automatizadas também têm limites.','Um fluxo de denúncia com justificativa e recurso pode ser avaliado por tipos de erro observados.','Quem responde pelo erro e como o usuário pode pedir revisão?'),fix('Plataformas digitais e autoridades competentes','Aumentar transparência sobre conteúdos sintéticos e canais de revisão.','Identificar anúncios e materiais alterados, publicar critérios e oferecer revisão humana em casos contestados.','Facilitar a avaliação responsável e corrigir decisões indevidas com prestação de contas.'),'Não trate qualquer uso de IA como engano nem confunda rótulo de origem com checagem factual.')],concepts:[{title:'Proveniência da informação',text:'Investigue autoria, publicação inicial, alterações e documentos que dão contexto.'},{title:'Alfabetização midiática',text:'Compare fontes independentes e diferencie fato verificável de interpretação ou opinião.'}],questions:['A ideia trata de origem, veracidade ou moderação? São questões distintas.','A proposta prevê contestação e correção de erro?','Não invente ferramentas, leis nem dados sobre circulação.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'inclusao',title:'Inclusão de pessoas com deficiência e neurodivergentes',axis:'Diversidade e direitos',proposals:['Desafios para garantir a participação social das pessoas neurodivergentes no Brasil','Como remover barreiras à participação de pessoas com deficiência','Inclusão escolar para além da matrícula'],keywords:['acessibilidade','deficiência','neurodivergência','autismo','capacitismo','altas habilidades','inclusão escolar'],routes:[
  route('acesso','Acessibilidade e remoção de barreiras','Barreiras pedagógicas, comunicacionais e físicas limitam a participação social quando instituições não planejam ambientes acessíveis com escuta das pessoas atendidas.',arg('Materiais e serviços padronizados podem impedir acesso e autonomia.','Um ambiente inacessível transforma uma característica individual em exclusão produzida pela organização do espaço.','Uma auditoria participativa pode percorrer um serviço público com usuários e registrar obstáculos encontrados.','Quem participou do mapeamento e qual barreira foi documentada?'),arg('A falta de formação e apoio contínuo enfraquece a inclusão escolar.','A matrícula não garante pertencimento quando adaptações e recursos são improvisados ou dependem de uma pessoa isolada.','Uma equipe escolar pode planejar adaptações com o estudante e a família, revendo-as conforme o que funciona.','Qual apoio é solicitado pela pessoa, em vez de presumido por terceiros?'),fix('Gestores de serviços públicos e redes de ensino','Adotar planos de acessibilidade construídos com pessoas com deficiência.','Auditar barreiras, definir responsáveis e prazos, adequar materiais e avaliar a solução com quem a utiliza.','Aumentar autonomia, acesso e participação sem apagar diferenças individuais.'),'Não fale por todo um grupo nem presuma que uma única adaptação atende a todas as pessoas.'),
  route('capacitismo','Representação e combate ao capacitismo','Estereótipos e baixa participação de pessoas com deficiência nas decisões reforçam práticas que tratam autonomia e diferenças como exceção.',arg('Estereótipos reduzem pessoas a limitações ou a histórias de superação.','Representações repetidas podem limitar o que o público considera possível e obscurecer barreiras institucionais.','Uma oficina pode analisar personagens e materiais públicos, verificando quem fala e que linguagem é usada.','A representação mostra agência e diversidade ou serve só como inspiração para terceiros?'),arg('Decisões sem consulta podem criar soluções incompatíveis com necessidades reais.','Projetos de acessibilidade funcionam melhor quando usuários participam desde a definição do problema.','Um conselho local com participação remunerada de usuários pode revisar um serviço antes de sua implantação.','A participação é contínua e influencia a decisão ou apenas valida algo pronto?'),fix('Órgãos públicos, escolas e produtores de comunicação','Instituir participação de pessoas com deficiência no planejamento e na comunicação.','Criar consultas acessíveis, remunerar colaborações e publicar como as contribuições influenciaram medidas adotadas.','Diminuir barreiras e ampliar a representação de experiências diversas.'),'Use a linguagem que o próprio grupo prefere e confirme referências antes de citar diagnósticos.' )],concepts:[{title:'Acessibilidade',text:'Avalie barreiras no ambiente, na comunicação, nos materiais e nas atitudes.'},{title:'Desenho universal',text:'Planejar produtos e espaços que sirvam ao maior número de pessoas, prevendo adaptações quando necessárias.'}],questions:['Quem definiu a barreira e participou da solução?','Matrícula ou acesso formal também significa participação efetiva?','Evite transformar deficiência em defeito individual a ser corrigido.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'educacao',title:'Alfabetização e desigualdade educacional',axis:'Educação e cultura',proposals:['Caminhos para garantir a alfabetização plena e reduzir desigualdades educacionais no Brasil','Desafios à alfabetização de crianças no Brasil','Como fortalecer a permanência e a aprendizagem escolar'],keywords:['alfabetização','analfabetismo','evasão','abandono escolar','aprendizagem','permanência escolar','alfabetismo'],routes:[
  route('apoio','Apoio pedagógico e desigualdade','Diferenças nas condições de acesso a materiais, tempo de aprendizagem e apoio pedagógico dificultam garantir alfabetização contínua a todos os estudantes.',arg('A aprendizagem não avança no mesmo ritmo quando faltam acompanhamento e materiais acessíveis.','Turmas heterogêneas precisam de diagnóstico pedagógico e apoio sem estigmatizar quem aprende em outro ritmo.','A escola pode analisar produções de escrita para planejar grupos temporários de apoio, revendo o plano após nova avaliação.','Como o acompanhamento identifica necessidade sem rotular a criança?'),arg('Desigualdades fora da sala de aula alteram as condições de frequência e estudo.','Transporte, alimentação, responsabilidades de cuidado e acesso a livros podem interferir na permanência.','Uma equipe local pode conversar com famílias, preservando sigilo, para identificar obstáculos à frequência.','A proposta atua sobre o obstáculo identificado ou exige que a família o resolva sozinha?'),fix('Redes públicas de ensino','Oferecer acompanhamento pedagógico contínuo e busca ativa acolhedora.','Formar equipes para monitorar aprendizagem e frequência, organizar apoio e articular encaminhamentos sociais quando necessário.','Garantir condições de continuidade e de desenvolvimento das aprendizagens.'),'Não use notas isoladas como prova de incapacidade nem equipare falta a desinteresse.'),
  route('permanencia','Permanência e equidade','Políticas uniformes de alfabetização têm alcance limitado quando desconsideram a diversidade linguística, territorial e de necessidades dos estudantes.',arg('Materiais pouco conectados à realidade da turma podem reduzir participação.','Conteúdos e exemplos que ignoram línguas, territórios e experiências locais dificultam a construção de sentido.','Professores podem selecionar textos de diferentes gêneros e contextos com participação dos alunos.','O material acrescenta repertório e também reconhece o que a turma já conhece?'),arg('Descontinuidade de programas e de equipes enfraquece ações de longo prazo.','Formação pontual sem tempo de planejamento não acompanha mudanças no aprendizado nem apoia professores.','Uma rede pode manter horários regulares de formação colaborativa e acompanhar indicadores por escola.','Qual acompanhamento permite corrigir o programa antes do fim do ano?'),fix('Secretarias de Educação e equipes escolares','Manter programas de alfabetização com formação e monitoramento territorial.','Reservar tempo de planejamento, adequar recursos aos contextos e revisar resultados com profissionais e famílias.','Reduzir desigualdades de oportunidade e apoiar práticas sustentáveis.'),'Diferencie oferta da escola, condições sociais e decisões de política pública; não atribua o problema a um só ator.')],concepts:[{title:'Direito à aprendizagem',text:'Verifique frequência, participação, materiais e apoio, além do acesso à matrícula.'},{title:'Avaliação formativa',text:'Usar evidências do percurso para ajustar o ensino, sem confundi-las com rótulo definitivo.'}],questions:['O argumento identifica uma barreira específica ao aprendizado?','O texto apresenta a criança como sujeito, sem culpabilizar famílias?','Qual evidência de contexto sustenta a leitura sobre a rede ou a escola?'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'trabalho',title:'Trabalho, informalidade e proteção social',axis:'Trabalho',proposals:['Desafios para garantir trabalho digno diante das novas relações de emprego no Brasil','Proteção social diante do trabalho mediado por plataformas','Reconhecimento e valorização do trabalho de cuidado no Brasil'],keywords:['trabalho','informalidade','plataforma','entregador','cuidado','proteção social','uberização','emprego'],routes:[
  route('protecoes','Proteção e previsibilidade','Relações de trabalho mediadas por plataformas podem combinar controle tecnológico e baixa previsibilidade de renda, enquanto a proteção social nem sempre acompanha a realidade ocupacional.',arg('A gestão por aplicativos pode reduzir a transparência sobre distribuição de tarefas e remuneração.','Sem conhecer critérios e canais de contestação, trabalhadores têm dificuldade para planejar renda ou corrigir erros.','Entrevistas consentidas e dados públicos podem comparar relatos sobre uma atividade, indicando período e limites da amostra.','Como o trabalhador pode conhecer e contestar uma decisão que afeta sua atividade?'),arg('A renda variável aumenta a dificuldade de planejar proteção diante de doença ou acidente.','Instabilidade e vínculos diversos podem tornar contribuições e acesso a direitos menos previsíveis.','Um orçamento hipotético pode comparar um mês de demanda alta e outro baixo, sem fingir que representa toda a categoria.','Que mecanismo protege a pessoa quando a renda varia ou o trabalho é interrompido?'),fix('Poder Público e atores econômicos envolvidos','Ampliar transparência e proteção adequada às formas contemporâneas de trabalho.','Publicar regras compreensíveis de remuneração, oferecer contestação e estudar mecanismos de proteção com participação dos trabalhadores.','Promover condições dignas, previsíveis e seguras.'),'Evite declarar vínculo jurídico ou atribuir direitos legais específicos sem conferir a legislação atual.'),
  route('reconhecimento','Cuidado e invisibilidade','A concentração do trabalho de cuidado em famílias e ocupações pouco reconhecidas pode ampliar desigualdades e restringir a participação social de quem cuida.',arg('O cuidado não remunerado consome tempo e pode limitar estudo e emprego.','Quando políticas e serviços não apoiam famílias, tarefas se concentram e tornam menos visível sua contribuição.','Um diário de tempo voluntário e anônimo pode revelar como tarefas se distribuem em uma amostra local.','Que dado mostraria quem realiza o cuidado e quanto tempo dedica?'),arg('O trabalho de cuidado remunerado pode ficar invisível nas estatísticas e no debate público.','Baixo reconhecimento dificulta formular condições e serviços compatíveis com a importância da atividade.','Uma análise pode comparar como diferentes funções de cuidado aparecem em materiais e debates locais, citando suas fontes.','Que experiência está ausente e que evidência ajuda a torná-la visível?'),fix('Órgãos de assistência social e políticas de trabalho','Reconhecer necessidades de cuidado na oferta de serviços e proteção.','Consultar trabalhadores e famílias, ampliar informação sobre serviços locais e monitorar acesso por território.','Distribuir melhor as responsabilidades e valorizar quem cuida.'),'Não presuma que todas as mulheres ou famílias vivem a mesma divisão de tarefas.')],concepts:[{title:'Proteção social',text:'Examine mecanismos que ajudam pessoas a enfrentar doença, acidentes ou perda de renda.'},{title:'Economia do cuidado',text:'Investigue como atividades remuneradas e não remuneradas sustentam a vida e são distribuídas.'}],questions:['O texto separa análise social de afirmações sobre o que a lei prevê hoje?','A solução foi construída com quem trabalha ou cuida?','Um exemplo hipotético não se torna estatística só por ser plausível.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'genero',title:'Violência de gênero e invisibilidade feminina',axis:'Diversidade e direitos',proposals:['Caminhos para enfrentar a violência de gênero e a radicalização nos ambientes digitais','Desafios para proteger mulheres da violência no espaço público e digital','Invisibilidade do trabalho de cuidado e desigualdade de gênero'],keywords:['violência de gênero','violência contra a mulher','misoginia','mulheres','cuidado','assédio','discriminação'],routes:[
  route('acolher','Prevenção e redes de proteção','A persistência da violência de gênero é agravada por normas que a naturalizam e por obstáculos para encontrar acolhimento e proteção adequados.',arg('Estereótipos podem normalizar comportamentos de controle e intimidação.','Piadas, ameaças e culpabilização diluem a percepção de violência e tornam mais difícil pedir ajuda.','Uma análise de campanhas ou materiais escolares pode identificar mensagens que reproduzem ou questionam estereótipos.','A linguagem responsabiliza quem sofreu violência ou questiona a conduta de quem a pratica?'),arg('A falta de informação sobre serviços dificulta o acesso à proteção.','Mesmo quando há canais, desconhecê-los ou recear exposição pode impedir sua utilização.','Uma rede local pode testar se materiais de orientação informam contatos atualizados e acessíveis.','O encaminhamento protege sigilo e considera a segurança da pessoa?'),fix('Redes locais de proteção, saúde e educação','Divulgar fluxos de acolhimento e fortalecer ações preventivas.','Produzir orientação acessível com serviços locais verificados, treinar equipes de primeira escuta e revisar encaminhamentos com especialistas.','Facilitar o acesso a apoio seguro e reduzir a naturalização da violência.'),'Não peça que a vítima confronte o agressor como condição para receber acolhimento.'),
  route('ambiente-digital','Assédio online e responsabilidade','A violência contra mulheres no espaço digital pode ser ampliada pela repetição de ataques e por canais de denúncia difíceis de acessar.',arg('Conteúdos misóginos podem intimidar e restringir a participação online.','A frequência e o alcance de ataques afetam a liberdade de expressão e a decisão de permanecer em comunidades digitais.','Uma auditoria pode medir tempos de resposta de canais públicos a relatos simulados, sem expor vítimas reais.','Que participação foi inibida e como isso foi documentado?'),arg('A remoção de conteúdo sem cuidado pode apagar provas ou expor ainda mais quem denuncia.','Resposta responsável precisa oferecer orientação, preservar escolhas e proteger dados pessoais.','Um fluxo de denúncia pode informar opções de bloqueio, registro e recurso antes de qualquer publicação adicional.','A medida devolve poder de decisão à pessoa afetada?'),fix('Plataformas e serviços públicos de acolhimento','Tornar canais de denúncia acessíveis e conectar plataformas a orientação segura.','Explicar opções, reduzir etapas, proteger dados e informar serviços de apoio verificados sem exigir exposição pública.','Reduzir barreiras à denúncia e apoiar escolhas seguras.'),'Não minimize ameaça por ocorrer na internet nem publique detalhes que identifiquem uma vítima.')],concepts:[{title:'Violência baseada em gênero',text:'Analise padrões de poder e barreiras de proteção sem presumir histórias individuais.'},{title:'Escuta e sigilo',text:'Acolher inclui preservar a autonomia e evitar a circulação desnecessária de relatos.'}],questions:['A proposta se coordena com serviços de apoio existentes?','Você evita culpabilizar ou expor a vítima?','Se usar números, verifique série, definição, fonte e ano.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'moradia',title:'Moradia e população em situação de rua',axis:'Cidadania e sociedade',proposals:['Desafios para assegurar moradia digna e proteção social à população em situação de rua','Caminhos para enfrentar o déficit habitacional urbano','Acolhimento e acesso a serviços pela população em situação de rua'],keywords:['moradia','habitação','situação de rua','déficit habitacional','aluguel','gentrificação','acolhimento'],routes:[
  route('servicos','Moradia e acesso a serviços','A insegurança habitacional é agravada pela oferta limitada de soluções estáveis e por barreiras para acessar documentação, saúde e assistência social.',arg('Sem moradia estável, atividades cotidianas e acesso a serviços tornam-se mais difíceis.','Guardar documentos, descansar e se deslocar para atendimento exige recursos que podem faltar a quem não tem endereço fixo.','Um mapa de serviços e horários de atendimento do município pode mostrar distâncias a percorrer, quando construído com usuários.','Que tarefa básica ou serviço exige um endereço ou deslocamento difícil?'),arg('Atendimentos fragmentados podem obrigar a pessoa a reconstruir sua história em vários locais.','Falta de coordenação e acolhimento com estigma enfraquece a continuidade do cuidado.','Uma rede local pode desenhar um fluxo de encaminhamento que evite repetir cadastro e exposição.','A intervenção reduz uma etapa ou apenas cria mais um serviço isolado?'),fix('Municípios e serviços de assistência, habitação e saúde','Articular acolhimento com acesso a moradia e serviços essenciais.','Mapear barreiras com participação de usuários, integrar encaminhamentos e acompanhar a continuidade do atendimento.','Fortalecer proteção social e acesso a direitos com respeito à dignidade.'),'Não descreva população em situação de rua como homogênea nem confunda assistência emergencial com política habitacional.'),
  route('habitação','Planejamento e permanência','O acesso precário à habitação pode se perpetuar quando a política urbana não articula disponibilidade de moradias, permanência e infraestrutura nos bairros.',arg('A distância entre habitação e serviços pode criar custos e isolamento.','Moradia acessível distante de trabalho, escola ou transporte impõe barreiras que podem comprometer permanência.','Comparar mapas públicos de transporte e equipamentos em projetos habitacionais ajuda a avaliar localização.','O plano oferece moradia em território conectado a quê?'),arg('Despejos e valorização imobiliária podem deslocar residentes de áreas com serviços.','Sem participação e proteção à permanência, melhorias urbanas podem beneficiar uns enquanto afastam outros.','Uma consulta pública pode levantar necessidades de moradores antes de uma obra, registrando propostas e respostas.','Quem decide sobre a mudança e como moradores participam?'),fix('Prefeituras e gestores de planejamento urbano','Planejar moradia junto com infraestrutura, transporte e serviços.','Publicar critérios de localização, ouvir residentes e acompanhar custos de deslocamento e permanência após a entrega.','Aumentar acesso à moradia digna sem aprofundar segregação urbana.'),'Não trate remoção como solução de visibilidade do problema; explique alternativas e proteção a direitos.')],concepts:[{title:'Direito à cidade',text:'Considere acesso a moradia, transporte, serviços, cultura e participação no território.'},{title:'Intersetorialidade',text:'Serviços de áreas distintas precisam coordenar encaminhamento e acompanhamento.'}],questions:['O texto diferencia resposta imediata e garantia duradoura de moradia?','Moradores participaram da definição da medida?','Evite usar “retirar das ruas” sem perguntar para onde, com que escolha e apoio.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'ciencia',title:'Ciência, saúde pública e automedicação',axis:'Saúde',proposals:['Caminhos para fortalecer a confiança na ciência e a informação responsável em saúde no Brasil','Desafios para comunicar evidências científicas à população','Como prevenir os riscos da automedicação com informação confiável'],keywords:['ciência','saúde pública','automedicação','vacina','divulgação científica','evidência','desinformação em saúde'],routes:[
  route('comunicacao','Comunicação acessível e fontes','A confiança em informações de saúde pode ser enfraquecida pela comunicação pouco acessível e pela circulação de alegações sem avaliação de evidências.',arg('Linguagem técnica pode excluir parte do público de debates que afetam seu cuidado.','Quando dúvidas ficam sem resposta compreensível, materiais simplificados por fontes duvidosas ocupam o espaço.','Uma unidade de saúde pode testar dois formatos de orientação com leitores voluntários e revisar trechos confusos.','Quem consegue compreender a mensagem e que dúvida permanece aberta?'),arg('Mensagens sem indicação de fonte ou contexto dificultam a checagem.','Uma conclusão científica precisa de autoria, escopo e limitações para ser interpretada com responsabilidade.','Uma atividade pode comparar uma postagem viral com a publicação ou nota institucional que ela cita.','A fonte sustenta exatamente a afirmação compartilhada?'),fix('Instituições de pesquisa e redes de saúde','Ampliar divulgação científica em linguagem acessível e verificável.','Produzir materiais com profissionais de comunicação e saúde, identificar fontes e atualizar respostas a dúvidas frequentes.','Ajudar o público a compreender evidências e localizar orientação confiável.'),'A redação não substitui avaliação profissional; evite prescrever ou recomendar tratamento.'),
  route('autonomia','Automedicação e acesso à orientação','A automedicação pode envolver busca por alívio rápido em contextos de acesso difícil à orientação, além de circulação de conselhos sem qualificação.',arg('A demora ou dificuldade de acesso pode levar pessoas a buscar soluções por conta própria.','Tempo, custo e distância influenciam decisões; isso não torna segura uma orientação sem avaliação adequada.','Um caso hipotético pode descrever alguém recorrendo a postagem viral diante de uma dúvida não atendida.','Que barreira de acesso aparece antes da decisão?'),arg('Recomendações virais podem apagar diferenças entre pessoas e situações clínicas.','Uma experiência individual não demonstra segurança ou eficácia para outras pessoas.','Uma oficina pode analisar exemplos simulados e marcar promessas que não citam fonte ou população estudada.','Que parte da mensagem tenta generalizar uma experiência?'),fix('Redes públicas de saúde e instituições de divulgação científica','Ampliar orientação pública acessível sobre evidências e serviços de saúde.','Reunir perguntas frequentes, indicar canais locais de atendimento e atualizar conteúdos revisados por profissionais habilitados.','Facilitar decisões informadas e reduzir dependência de recomendações sem contexto.'),'Não reproduza doses, tratamentos ou alegações clínicas não verificadas.' )],concepts:[{title:'Evidência científica',text:'Pergunte qual método, população, incerteza e revisão sustentam uma afirmação.'},{title:'Risco relativo e contexto',text:'Uma afirmação responsável informa para quem, quando e em que condições se aplica.'}],questions:['O texto distingue dúvida legítima de desinformação deliberada?','A fonte consultada é compatível com a afirmação usada?','Não transforme associação observada em causa comprovada.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'juventude',title:'Violência e oportunidades para a juventude',axis:'Infância e juventude',proposals:['Desafios para garantir segurança e oportunidades à juventude brasileira','Como ampliar o acesso de jovens à cultura, estudo e trabalho','Prevenção da violência por meio de proteção e oportunidades'],keywords:['juventude','violência juvenil','primeiro emprego','oportunidade','jovem','cultura','esporte','evasão escolar'],routes:[
  route('oportunidade','Oportunidades e proteção','A exposição de jovens à violência é influenciada por desigualdades de acesso a direitos e por respostas públicas que chegam de maneira desigual aos territórios.',arg('A ausência de espaços de convivência e oportunidades restringe alternativas de participação.','Escola, esporte, cultura e trabalho digno podem ampliar escolhas quando acessíveis e contínuos.','Um inventário comunitário pode mapear quadras, bibliotecas e programas por horário e bairro.','A oportunidade existe no papel ou é acessível no horário e território do jovem?'),arg('Políticas centradas apenas em punição deixam prevenção e proteção em segundo plano.','Abordagens sem escuta podem afastar jovens dos serviços capazes de responder a riscos e necessidades.','Um conselho juvenil pode avaliar acolhimento em equipamentos públicos e propor ajustes acompanhados.','A medida protege o jovem e também reconhece sua voz?'),fix('Gestores municipais de Educação, Cultura e Assistência Social','Criar percursos locais de acesso a atividades e proteção para jovens.','Articular equipamentos existentes, reservar vagas e horários acessíveis e acompanhar participação com conselhos juvenis.','Ampliar escolhas, pertencimento e acesso a apoio nos territórios.'),'Evite associar juventude, raça ou território à criminalidade sem evidências; proteja grupos contra estigmas.'),
  route('trabalho','Permanência escolar e transição','Permanecer na escola e chegar ao primeiro emprego digno pode ser difícil quando renda, responsabilidades familiares e formação profissional se chocam.',arg('A necessidade de renda pode competir com tempo de estudo e descanso.','Sem apoio compatível, a transição para o trabalho pode ampliar abandono escolar ou ocupações instáveis.','Uma pesquisa voluntária pode perguntar a estudantes sobre horários de trabalho e barreiras de transporte.','Como a proposta considera rotina e renda em vez de simplesmente exigir disponibilidade?'),arg('Informações e redes de acesso ao primeiro emprego são distribuídas de forma desigual.','Orientação profissional e experiências práticas ajudam quando acessíveis a diferentes escolas e bairros.','Uma escola pode convidar profissionais de setores variados e oferecer oficinas abertas a turmas diversas.','Quem não recebe a informação e como alcançar esse público?'),fix('Escolas, serviços de juventude e empregadores participantes','Oferecer orientação e experiências de transição escola-trabalho compatíveis com a permanência escolar.','Articular oficinas, informação acessível e oportunidades com horários previsíveis e salvaguardas para jovens.','Apoiar autonomia e formação sem afastar estudantes da escola.'),'Não transforme “oportunidade” em promessa de vaga ou solução individual para desemprego estrutural.')],concepts:[{title:'Prevenção social',text:'Agir nas condições que expõem pessoas a riscos e fortalecer fatores de proteção coletiva.'},{title:'Participação juvenil',text:'Jovens conhecem obstáculos do cotidiano e precisam influenciar a política que os afeta.'}],questions:['O texto evita associar automaticamente pobreza e violência?','A oportunidade descrita tem horário, acesso e responsável definidos?','Consulte fonte atual se citar estatísticas de violência.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'democracia',title:'Participação social e cidadania',axis:'Cidadania e sociedade',proposals:['Caminhos para ampliar a participação social na construção de políticas públicas brasileiras','Acesso à informação e participação cidadã no Brasil','Desafios à representação de diferentes grupos nos espaços de decisão'],keywords:['cidadania','participação','representação política','acesso à informação','políticas públicas','registro civil','conselho local'],routes:[
  route('acesso-informacao','Informação e canais de participação','A desigualdade no acesso a informações claras e a espaços de decisão limita a participação cidadã de grupos menos representados.',arg('Consultas públicas pouco acessíveis afastam pessoas afetadas pelas decisões.','Horários, linguagem técnica e ausência de devolutiva fazem a participação parecer simbólica.','Uma audiência local pode publicar contribuições recebidas e explicar quais foram incorporadas.','Quem pôde participar e o que aconteceu com as contribuições?'),arg('A desinformação sobre serviços e decisões dificulta o exercício da cidadania.','Informações dispersas sobre prazos e canais aumentam erros e reduzem confiança.','Um município pode consolidar orientações em uma página simples, com versão impressa em equipamentos públicos.','A informação chega também a quem tem conexão limitada?'),fix('Gestores públicos e conselhos de políticas','Tornar consultas e informações públicas acessíveis e transparentes.','Oferecer mais de um canal, horário previsível, linguagem simples e devolutiva que registre encaminhamentos.','Ampliar participação informada e mostrar como as contribuições foram consideradas.'),'Participação não se resume a comparecer: importa influência, diversidade e retorno.'),
  route('representacao','Representação e escuta','Quando os espaços de decisão não refletem a diversidade das comunidades afetadas, políticas podem deixar barreiras importantes sem resposta.',arg('Custos de participação e critérios de entrada podem excluir pessoas com menos tempo ou recursos.','Deslocamento, cuidado de familiares e reuniões sem acessibilidade limitam quem consegue permanecer.','Um conselho pode testar participação remota e apoio de transporte, avaliando quem passa a participar.','Que custo concreto impede alguém de falar e qual ajuste o reduz?'),arg('Falta de retorno desestimula contribuições futuras.','A pessoa que compartilha uma experiência quer saber se a informação foi analisada e o que mudou.','Uma consulta pode divulgar uma matriz pública com temas recebidos, decisões e justificativas.','Como a instituição demonstra que escutou mesmo quando não adota uma sugestão?'),fix('Órgãos responsáveis por consultas e conselhos locais','Revisar as condições de participação e criar devolutivas públicas.','Identificar barreiras com grupos afetados, adaptar canais e explicar decisões em linguagem acessível.','Fortalecer a confiança e a representatividade na elaboração de políticas.'),'Não trate toda consulta como retrato da opinião de toda a população.')],concepts:[{title:'Transparência pública',text:'Informação acessível e rastreável permite que a sociedade acompanhe decisões.'},{title:'Representatividade',text:'Observe quem participa, quais experiências chegam e como são consideradas.'}],questions:['Que grupo afetado ainda não está representado?','A instituição explica o destino das contribuições?','Não use “o povo pensa” com base em uma amostra pequena.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'idosos',title:'Envelhecimento e combate ao etarismo',axis:'Diversidade e direitos',proposals:['Desafios para promover autonomia e inclusão da população idosa no Brasil','Como ampliar a inclusão digital de pessoas idosas','Combate ao etarismo nas relações de trabalho e na sociedade'],keywords:['idoso','envelhecimento','etarismo','inclusão digital','autonomia','acessibilidade','cuidado'],routes:[
  route('autonomia','Autonomia e redes de cuidado','A participação social de pessoas idosas é limitada por ambientes pouco acessíveis, estereótipos sobre envelhecimento e apoio insuficiente a diferentes necessidades de cuidado.',arg('Estereótipos podem tratar pessoas idosas como um grupo sem autonomia ou planos próprios.','Quando instituições presumem incapacidade, limitam oportunidades de participação e decisão.','Uma pesquisa de linguagem em anúncios ou serviços pode verificar como idade e autonomia são retratadas.','A pessoa idosa é consultada sobre a decisão ou apenas descrita por terceiros?'),arg('Barreiras em transporte, serviços e espaços digitais reduzem acesso cotidiano.','Interfaces e rotinas projetadas sem diversidade de usuários tornam tarefas simples dependentes de terceiros.','Uma avaliação voluntária de um serviço digital pode reunir usuários de diferentes níveis de familiaridade.','Qual etapa do serviço pode ganhar acessibilidade sem exigir que alguém peça ajuda?'),fix('Gestores municipais e prestadores de serviços','Revisar acessibilidade e participação em serviços usados por pessoas idosas.','Realizar testes com usuários, oferecer atendimento em mais de um canal e capacitar equipes para escuta respeitosa.','Aumentar autonomia e convivência, respeitando escolhas individuais.'),'Não trate idade como diagnóstico nem presuma que toda pessoa idosa usa ou rejeita tecnologia.'),
  route('participacao','Idade, trabalho e convivência','Práticas etaristas podem excluir pessoas idosas de relações de trabalho, convivência e aprendizagem mesmo quando desejam participar.',arg('Seleção e formação podem reproduzir pressupostos sobre idade e capacidade.','Exigências sem relação com a função e oportunidades concentradas em poucos grupos podem reforçar exclusão.','Uma organização pode comparar quem recebe convites de formação por faixa etária, respeitada a privacidade.','Que critério avalia competência e qual apenas presume limitação?'),arg('A convivência intergeracional fica restrita quando serviços separam públicos por idade.','Troca entre gerações pode surgir de projetos comuns com papéis e respeito mútuo.','Uma atividade de troca de saberes pode ser construída com participantes que escolhem o que desejam compartilhar.','Quem define o objetivo e o benefício esperado da atividade?'),fix('Empregadores e gestores de equipamentos comunitários','Revisar regras de acesso e promover oportunidades intergeracionais.','Auditar critérios, divulgar formação e coorganizar atividades abertas com participação voluntária.','Reduzir barreiras sem impor papéis ou tarefas pela idade.'),'Consulte as pessoas afetadas e preserve suas escolhas; evite falar de envelhecimento só como dependência.')],concepts:[{title:'Etarismo',text:'Identifique julgamentos e barreiras baseados na idade, inclusive os apresentados como “naturais”.'},{title:'Autonomia',text:'Significa poder participar das decisões que afetam a própria rotina e os próprios objetivos.'}],questions:['O texto reconhece diversidade entre pessoas idosas?','A tecnologia proposta oferece alternativa acessível de atendimento?','Não confunda companhia, cuidado e substituição da autonomia.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'cultura',title:'Diversidade cultural e povos tradicionais',axis:'Educação e cultura',proposals:['Desafios para preservar o patrimônio cultural de comunidades tradicionais brasileiras','Caminhos para valorizar saberes e expressões culturais brasileiras','Participação de comunidades tradicionais nas políticas culturais'],keywords:['cultura','patrimônio cultural','povos tradicionais','povos indígenas','afro-brasileiro','museu','identidade cultural'],routes:[
  route('participacao-cultural','Preservação com participação','A preservação do patrimônio cultural pode produzir apagamento quando decisões são tomadas sem participação das comunidades que mantêm práticas, memórias e saberes.',arg('Registros institucionais podem privilegiar a visão de quem documenta.','Sem consentimento e contexto, uma prática cultural pode ser transformada em objeto exótico separado de seus guardiões.','Um projeto de memória pode acordar previamente com a comunidade o que registrar, como guardar e o que não divulgar.','Quem decide sobre o registro, o acesso e a circulação do material?'),arg('Falta de apoio contínuo fragiliza a transmissão entre gerações.','Espaços, tempo e reconhecimento são necessários para que mestres e aprendizes compartilhem práticas.','Uma iniciativa local pode organizar oficinas conduzidas por representantes escolhidos pela própria comunidade.','A ação tem continuidade e reconhece a autoria de quem ensina?'),fix('Gestores de políticas culturais, junto às comunidades','Financiar iniciativas de preservação desenhadas pelos próprios grupos.','Criar editais acessíveis, assegurar consulta e prever regras de consentimento e guarda dos registros.','Fortalecer a continuidade cultural com autoria e participação comunitária.'),'Não descreva um povo como homogêneo nem publique saberes que a comunidade não deseja compartilhar.'),
  route('acesso-cultural','Acesso e circulação cultural','A desigualdade de acesso a equipamentos e de reconhecimento de diferentes expressões culturais restringe a participação e a circulação de obras.',arg('Equipamentos culturais concentrados em algumas áreas aumentam custo e tempo de acesso.','Transporte, horários e preço podem limitar quem usufrui de programação pública.','Um mapa de localização, horários e itinerários pode orientar um circuito de atividades culturais gratuitas.','A atividade é acessível também para quem mora longe ou tem mobilidade reduzida?'),arg('Pouca presença de autores e artistas diversos em programações reduz visibilidade.','Curadoria sem diálogo pode repetir hierarquias e deixar expressões locais de fora.','Uma comissão comunitária pode propor programação e critérios de seleção transparentes.','Quem escolheu os artistas e como o processo foi divulgado?'),fix('Secretarias de Cultura e equipamentos públicos','Ampliar circulação e participação na programação cultural local.','Combinar atividades itinerantes, critérios públicos de seleção e consulta a grupos de diferentes territórios.','Aproximar equipamentos e expressões culturais de públicos diversos.'),'Valorizar não é apropriar: indique autoria, contexto e consentimento.')],concepts:[{title:'Patrimônio cultural',text:'Pode envolver práticas, celebrações, saberes, memórias e expressões preservadas por comunidades.'},{title:'Autodeterminação e consentimento',text:'As comunidades devem influenciar como são representadas e como registros circulam.'}],questions:['Quem é responsável por definir o que preservar?','A proposta oferece autoria e continuidade à comunidade?','Evite generalizações culturais ou datas históricas sem conferir a fonte.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'fome',title:'Segurança alimentar e desigualdade',axis:'Cidadania e sociedade',proposals:['Caminhos para garantir segurança alimentar à população brasileira','Desafios para ampliar o acesso regular a alimentos adequados','Desperdício, distribuição e acesso à alimentação no Brasil'],keywords:['insegurança alimentar','fome','alimentação','desperdício','renda','agricultura','merenda'],routes:[
  route('acesso-regular','Renda e acesso regular','A insegurança alimentar está ligada a condições materiais e a redes de abastecimento desiguais, o que torna insuficiente tratar a fome como escolha individual.',arg('Variação de renda e custo dos alimentos pode comprometer a regularidade do acesso.','Famílias com orçamento restrito têm menos margem para absorver aumentos ou imprevistos.','Uma análise de orçamento familiar hipotético pode comparar gastos essenciais sem fingir que mede uma população real.','Que recurso e que preço sustentam sua afirmação sobre acesso?'),arg('A oferta local e a distância de pontos de abastecimento afetam escolhas possíveis.','Estar perto de alimentos adequados e conseguir transportá-los influenciam a rotina.','Um mapa de feira, mercado e transporte pode revelar lacunas de acesso em determinado bairro.','A disponibilidade está no território e no horário de que a família precisa?'),fix('Gestores de assistência social e abastecimento, em cooperação local','Ampliar acesso estável a alimentos e informações sobre apoio disponível.','Mapear áreas atendidas, coordenar serviços locais e acompanhar regularidade com famílias participantes.','Reduzir interrupções no acesso e melhorar a segurança alimentar.'),'Não reduza pobreza alimentar a falta de educação nutricional nem recomende dietas como resposta estrutural.'),
  route('desperdicio','Produção, perdas e distribuição','Perdas evitáveis e dificuldades de coordenação entre produção, comércio e instituições podem coexistir com barreiras de acesso a alimentos.',arg('A logística e o armazenamento inadequados podem contribuir para perdas.','Distância, refrigeração e planejamento interferem na capacidade de preservar produtos.','Uma cooperativa pode registrar perdas em etapas distintas antes de escolher uma solução de armazenagem.','Em qual etapa a perda foi observada e qual causa pode ser corrigida?'),arg('Doação pontual não substitui acesso regular nem resolve a distribuição desigual.','Ações emergenciais respondem a uma necessidade imediata, enquanto políticas de renda e abastecimento atuam na continuidade.','Um banco de alimentos pode definir critérios transparentes e acompanhar origem e destino dos produtos.','A medida complementa uma política contínua ou ocupa o lugar dela?'),fix('Redes locais de abastecimento e assistência social','Melhorar a coordenação contra perdas e fortalecer o encaminhamento alimentar.','Registrar perdas, firmar acordos com segurança sanitária e divulgar de forma acessível os canais públicos existentes.','Aproveitar alimentos em condições adequadas e apoiar o acesso regular.'),'Segurança sanitária e dignidade das famílias precisam orientar qualquer distribuição.')],concepts:[{title:'Segurança alimentar',text:'Considere acesso regular, disponibilidade, adequação e estabilidade ao longo do tempo.'},{title:'Abastecimento',text:'Analise produção, armazenamento, transporte, comércio e destino dos alimentos.'}],questions:['O texto explica a origem da barreira ao acesso?','Uma ação emergencial está claramente separada da política contínua?','Atualize dados de fome com fonte, período e definição.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]},
 {id:'acesso',title:'Inclusão digital e acesso à informação',axis:'Tecnologia e informação',proposals:['Desafios para ampliar a inclusão digital e o acesso qualificado à informação no Brasil','Como diminuir barreiras de acesso a serviços digitais','Inclusão digital para além da conexão à internet'],keywords:['inclusão digital','internet','conexão','acesso digital','acessibilidade digital','serviços online','letramento digital'],routes:[
  route('infraestrutura','Infraestrutura e território','A exclusão digital persiste quando conectividade de qualidade, equipamentos e serviços acessíveis são distribuídos de modo desigual entre territórios e grupos.',arg('A disponibilidade de sinal não garante conexão estável e adequada para estudar ou trabalhar.','Cobertura, preço e qualidade influenciam a possibilidade de acessar serviços e conteúdos.','Uma pesquisa local pode comparar sinal em pontos públicos em horários diferentes, descrevendo método e limites.','Que medida de conexão importa além de dizer que “tem internet”?'),arg('Serviços exclusivamente digitais podem excluir quem não dispõe de aparelho ou apoio.','Digitalizar um serviço sem alternativa não reduz a barreira para quem tem conexão instável ou deficiência.','Um teste de serviço pode observar quantas etapas exigem aparelho recente ou autenticação difícil.','Existe atendimento alternativo equivalente e acessível?'),fix('Gestores públicos e provedores de conectividade','Mapear lacunas de acesso e manter alternativas acessíveis aos serviços digitais.','Ouvir territórios, priorizar conectividade pública e oferecer canais presenciais ou assistidos enquanto persistirem barreiras.','Ampliar acesso efetivo à informação e a serviços.'),'Não use acesso à internet como sinônimo de uso qualificado ou de igualdade digital.'),
  route('autonomia-digital','Autonomia e acessibilidade','Mesmo conectado, o usuário pode depender de terceiros quando serviços digitais não são compreensíveis, acessíveis ou compatíveis com suas necessidades.',arg('Interfaces confusas tornam direitos e tarefas difíceis de exercer.','Etapas obscuras e linguagem técnica aumentam erros e fazem usuários abandonarem serviços.','Um grupo voluntário pode concluir uma tarefa simulada e apontar em qual etapa ficou em dúvida.','A dificuldade está na habilidade do usuário ou no desenho da interface?'),arg('A falta de formação prática impede aproveitar recursos disponíveis.','Orientação em contexto ajuda a avaliar fontes, proteger dados e concluir tarefas.','Uma biblioteca pode oferecer atendimento para uso de serviços públicos com materiais em linguagem simples.','A formação aumenta autonomia sem coletar senha ou fazer a tarefa no lugar da pessoa?'),fix('Bibliotecas, escolas e equipes responsáveis por serviços digitais','Oferecer formação digital e revisar acessibilidade de serviços essenciais.','Realizar oficinas práticas, testar interfaces com usuários e manter apoio presencial sem exigir compartilhamento de senhas.','Aumentar autonomia e acesso seguro, preservando privacidade.'),'Não atribua exclusão apenas à “falta de habilidade”; investigue aparelho, conexão, linguagem e acessibilidade.')],concepts:[{title:'Inclusão digital',text:'Observe conexão, equipamento, acessibilidade, competências e condições de participação.'},{title:'Desenho centrado no usuário',text:'Testar tarefas com pessoas reais permite identificar barreiras antes da publicação.'}],questions:['Qual etapa concreta impede o acesso?','A alternativa presencial protege o mesmo direito enquanto a barreira permanece?','Não compare grupos sem definir local, período e indicador.'],sources:[{title:'Inep · Cartilha da Redação 2026',url:officialINEP}]}
];
// Keep the first practice prompt aligned with the exact proposal selected in Radar.
for(const idea of essayIdeas){
 const radarTopic=radarTopics.find(topic=>topic.id===idea.id);
 if(radarTopic){const alternates=idea.proposals.filter(prompt=>prompt!==radarTopic.proposal);idea.proposals=[radarTopic.proposal,alternates[0]||radarTopic.proposal,alternates[1]||radarTopic.proposal];}
}
